import androidx.compose.foundation.shape.RoundedCornerShape
import com.example.digitaltrainer.ui.screens.onboarding.components.OnboardingHeader
import com.example.digitaltrainer.ui.screens.onboarding.components.PrimaryButton

@Composable
fun PlanComparisonScreen(
    onBack: () -> Unit,
    onNext: () -> Unit
) {
    Column {
        OnboardingHeader(
            title = "Let's Make Your Fitness\nEasier & More Effective!",
            onBack = onBack,
            height = 200.dp
        )
        Column(
            modifier = Modifier
                .fillMaxWidth()
                .padding(24.dp),
            verticalArrangement = Arrangement.spacedBy(24.dp)
        ) {
            Row(
                horizontalArrangement = Arrangement.spacedBy(12.dp),
                modifier = Modifier.fillMaxWidth()
            ) {
                PlanCard(
                    title = "Our Plan",
                    points = listOf(
                        "Faster changes",
                        "Fits you perfectly",
                        "Easy to follow",
                        "Lasting results"
                    ),
                    modifier = Modifier.weight(1f),
                    highlight = true
                )
                PlanCard(
                    title = "Others' Plan",
