    val background = if (highlight) Color(0xFF7C3AED) else Color.White
    val contentColor = if (highlight) Color.White else MaterialTheme.colorScheme.onSurface
    Card(
        modifier = modifier,
        colors = CardDefaults.cardColors(containerColor = background),
